@Tags(['golden'])
library;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zaghlol/features/capture/presentation/capture_settings_screen.dart';

import '../../../support/golden_matrix.dart';
import 'capture_ui_support.dart';
import 'card_capture_sheet_test.dart' as sheet;

// Goldens are generated by CI (`--update-goldens`); PNGs are not committed.
void main() {
  for (final v in goldenVariants) {
    testWidgets('capture settings golden ${v.name}', (t) async {
      await t.binding.setSurfaceSize(const Size(390, 1500));
      addTearDown(() => t.binding.setSurfaceSize(null));
      await t.pumpWidget(
        host(
          const CaptureSettingsScreen(),
          controls: FakeControls(
            rules: [
              rule('1', 'cib', '9910', 'sms'),
              rule('2', 'cib', '9910', 'notification'),
              rule('3', 'revolut', null, 'notification'),
            ],
          ),
          locale: v.locale,
          dark: v.dark,
        ),
      );
      await t.pumpAndSettle();
      await expectLater(
        find.byType(MaterialApp),
        matchesGoldenFile('../../../goldens/capture_settings_${v.name}.png'),
      );
    });

    testWidgets('card capture controls golden ${v.name}', (t) async {
      await t.binding.setSurfaceSize(const Size(390, 520));
      addTearDown(() => t.binding.setSurfaceSize(null));
      await t.pumpWidget(
        host(
          sheet.sheet(),
          controls: FakeControls(rules: [rule('1', 'cib', '1234', 'sms')]),
          locale: v.locale,
          dark: v.dark,
        ),
      );
      await t.pumpAndSettle();
      await expectLater(
        find.byType(MaterialApp),
        matchesGoldenFile('../../../goldens/card_capture_${v.name}.png'),
      );
    });
  }
}
